CREATE TABLE el_departments(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES el_organizations(id),branch_id TEXT NOT NULL,name TEXT NOT NULL,manager TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),UNIQUE(org_id,branch_id,name),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_employees(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,department_id TEXT,teacher_id TEXT,user_id TEXT,code TEXT NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',job_title TEXT NOT NULL,emergency_contact TEXT NOT NULL DEFAULT '',hired_on TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','onboarding','on_leave','resigned','terminated')),notes TEXT NOT NULL DEFAULT '',is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),UNIQUE(org_id,code),UNIQUE(org_id,user_id),UNIQUE(org_id,teacher_id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,department_id) REFERENCES el_departments(org_id,id),FOREIGN KEY(org_id,teacher_id) REFERENCES el_teachers(org_id,id),FOREIGN KEY(org_id,user_id) REFERENCES el_memberships(org_id,user_id));
CREATE TABLE el_contracts(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,employee_id TEXT NOT NULL,title TEXT NOT NULL,starts_on TEXT NOT NULL,ends_on TEXT NOT NULL,salary INTEGER NOT NULL CHECK(typeof(salary)='integer' AND salary>=0),hours_per_day INTEGER NOT NULL DEFAULT 8 CHECK(hours_per_day BETWEEN 1 AND 24),notes TEXT NOT NULL DEFAULT '',is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(ends_on>=starts_on),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES el_employees(org_id,id));
CREATE TABLE el_employee_attendance(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,employee_id TEXT NOT NULL,date TEXT NOT NULL,arrival TEXT NOT NULL DEFAULT '',departure TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN ('present','absent','late','excused')),minutes INTEGER NOT NULL DEFAULT 0 CHECK(minutes>=0 AND minutes<=1440),notes TEXT NOT NULL DEFAULT '',created_by TEXT NOT NULL REFERENCES el_users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,is_demo INTEGER NOT NULL DEFAULT 0,UNIQUE(employee_id,date),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES el_employees(org_id,id));
CREATE TABLE el_leave_requests(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,employee_id TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN ('vacation','sick','unpaid','other')),starts_on TEXT NOT NULL,ends_on TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),created_by TEXT NOT NULL REFERENCES el_users(id),decided_by TEXT REFERENCES el_users(id),decision_note TEXT NOT NULL DEFAULT '',is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),CHECK(ends_on>=starts_on),FOREIGN KEY(org_id,employee_id) REFERENCES el_employees(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TRIGGER el_leave_guard BEFORE UPDATE ON el_leave_requests BEGIN SELECT CASE WHEN OLD.status<>'pending' OR NEW.status NOT IN ('approved','rejected') OR NEW.created_by=NEW.decided_by THEN RAISE(ABORT,'Leave decision requires another user and pending request') END;SELECT CASE WHEN NEW.status='approved' AND EXISTS(SELECT 1 FROM el_leave_requests WHERE employee_id=NEW.employee_id AND id<>NEW.id AND status='approved' AND starts_on<=NEW.ends_on AND ends_on>=NEW.starts_on) THEN RAISE(ABORT,'Approved leave overlaps existing leave') END;END;
CREATE TABLE el_employee_reviews(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,employee_id TEXT NOT NULL,date TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN ('performance','disciplinary','onboarding','resignation','termination')),rating INTEGER NOT NULL DEFAULT 0 CHECK(rating BETWEEN 0 AND 5),notes TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES el_users(id),is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(org_id,employee_id) REFERENCES el_employees(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_applications(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',job_title TEXT NOT NULL,stage TEXT NOT NULL DEFAULT 'applied' CHECK(stage IN ('applied','screening','interview','offer','hired','rejected')),interview_at INTEGER,notes TEXT NOT NULL DEFAULT '',employee_id TEXT,is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES el_employees(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_campaigns(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,name TEXT NOT NULL,channel TEXT NOT NULL CHECK(channel IN ('website','facebook','instagram','whatsapp','phone','walk_in','referral','other')),starts_on TEXT NOT NULL,ends_on TEXT NOT NULL,budget INTEGER NOT NULL DEFAULT 0 CHECK(typeof(budget)='integer' AND budget>=0),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','completed','paused')),notes TEXT NOT NULL DEFAULT '',is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),CHECK(ends_on>=starts_on),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_leads(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',source TEXT NOT NULL,campaign_id TEXT,assigned_to TEXT,stage TEXT NOT NULL DEFAULT 'new' CHECK(stage IN ('new','contacted','interested','trial_booked','trial_attended','negotiation','registered','lost')),follow_up_on TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',student_id TEXT,is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,campaign_id) REFERENCES el_campaigns(org_id,id),FOREIGN KEY(org_id,assigned_to) REFERENCES el_memberships(org_id,user_id),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id));
CREATE TABLE el_lead_interactions(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,lead_id TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN ('call','message','visit','note')),notes TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES el_users(id),is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(org_id,lead_id) REFERENCES el_leads(org_id,id));
CREATE TRIGGER el_lead_conversion_guard BEFORE UPDATE ON el_leads WHEN OLD.student_id IS NOT NULL AND (NEW.student_id IS NOT OLD.student_id OR NEW.stage<>'registered') BEGIN SELECT RAISE(ABORT,'Converted lead cannot be converted again'); END;
CREATE TABLE el_visits(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',purpose TEXT NOT NULL,host TEXT NOT NULL DEFAULT '',scheduled_at INTEGER NOT NULL,checked_in INTEGER,checked_out INTEGER,notes TEXT NOT NULL DEFAULT '',is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_announcements(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT,title TEXT NOT NULL,body TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES el_users(id),is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_notifications(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,user_id TEXT NOT NULL,announcement_id TEXT,title TEXT NOT NULL,body TEXT NOT NULL,read_at INTEGER,is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),FOREIGN KEY(org_id,user_id) REFERENCES el_memberships(org_id,user_id),FOREIGN KEY(org_id,announcement_id) REFERENCES el_announcements(org_id,id));
CREATE TABLE el_delivery_logs(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,announcement_id TEXT NOT NULL,user_id TEXT NOT NULL,channel TEXT NOT NULL DEFAULT 'in_app',status TEXT NOT NULL CHECK(status IN ('stored','read','blocked')),detail TEXT NOT NULL DEFAULT '',is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(org_id,announcement_id) REFERENCES el_announcements(org_id,id),FOREIGN KEY(org_id,user_id) REFERENCES el_memberships(org_id,user_id));
CREATE TABLE el_notification_preferences(org_id TEXT NOT NULL,user_id TEXT NOT NULL,in_app INTEGER NOT NULL DEFAULT 1,is_demo INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(org_id,user_id),FOREIGN KEY(org_id,user_id) REFERENCES el_memberships(org_id,user_id));
CREATE INDEX el_employees_lookup ON el_employees(org_id,branch_id,status,name);
CREATE INDEX el_departments_lookup ON el_departments(org_id,branch_id,status);
CREATE INDEX el_contracts_employee ON el_contracts(org_id,employee_id,ends_on);
CREATE INDEX el_employee_attendance_lookup ON el_employee_attendance(org_id,branch_id,date,employee_id);
CREATE INDEX el_leave_requests_lookup ON el_leave_requests(org_id,branch_id,status,starts_on);
CREATE INDEX el_employee_reviews_lookup ON el_employee_reviews(org_id,employee_id,date);
CREATE INDEX el_applications_lookup ON el_applications(org_id,branch_id,stage,name);
CREATE INDEX el_campaigns_lookup ON el_campaigns(org_id,branch_id,status,starts_on);
CREATE INDEX el_leads_lookup ON el_leads(org_id,branch_id,stage,name);
CREATE INDEX el_lead_interactions_lookup ON el_lead_interactions(org_id,lead_id,created_at);
CREATE INDEX el_visits_lookup ON el_visits(org_id,branch_id,scheduled_at);
CREATE INDEX el_notifications_lookup ON el_notifications(org_id,user_id,read_at,created_at);
CREATE INDEX el_announcements_lookup ON el_announcements(org_id,branch_id,created_at);
CREATE INDEX el_delivery_logs_lookup ON el_delivery_logs(org_id,announcement_id,user_id);
CREATE TRIGGER el_application_hire_guard BEFORE UPDATE ON el_applications WHEN OLD.stage='hired' BEGIN SELECT RAISE(ABORT,'Hired application is immutable'); END;
CREATE TRIGGER el_visit_guard BEFORE UPDATE ON el_visits BEGIN SELECT CASE WHEN OLD.checked_out IS NOT NULL OR (OLD.checked_in IS NOT NULL AND NEW.checked_in IS NOT OLD.checked_in) THEN RAISE(ABORT,'Visitor check state is immutable') END; END;
CREATE TABLE el_coupons(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,name TEXT NOT NULL,code TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN ('fixed','percent')),value INTEGER NOT NULL CHECK(typeof(value)='integer' AND value>0),starts_on TEXT NOT NULL,ends_on TEXT NOT NULL,max_uses INTEGER NOT NULL DEFAULT 100 CHECK(max_uses>0),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),UNIQUE(org_id,code),CHECK(ends_on>=starts_on),CHECK(type<>'percent' OR value<=100),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
ALTER TABLE el_invoices ADD COLUMN coupon_id TEXT REFERENCES el_coupons(id);
CREATE INDEX el_coupons_lookup ON el_coupons(org_id,branch_id,status,code);
CREATE INDEX el_invoice_coupon ON el_invoices(coupon_id,status);
CREATE TRIGGER el_coupon_issue_guard BEFORE UPDATE OF status ON el_invoices WHEN NEW.status='issued' AND NEW.coupon_id IS NOT NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_coupons c WHERE c.id=NEW.coupon_id AND c.org_id=NEW.org_id AND c.branch_id=NEW.branch_id AND c.status='active' AND c.starts_on<=NEW.date AND c.ends_on>=NEW.date AND (SELECT count(*) FROM el_invoices WHERE coupon_id=c.id AND status IN ('issued','void'))<c.max_uses) THEN RAISE(ABORT,'Coupon is expired, exhausted or unavailable') END; END;
ALTER TABLE el_contracts ADD COLUMN workweek TEXT NOT NULL DEFAULT '';
ALTER TABLE el_contracts ADD COLUMN overtime_rate INTEGER NOT NULL DEFAULT 0 CHECK(overtime_rate>=0);
CREATE TABLE el_staff_payroll(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,employee_id TEXT NOT NULL,contract_id TEXT NOT NULL,month TEXT NOT NULL,calculation_json TEXT NOT NULL,total INTEGER NOT NULL CHECK(typeof(total)='integer' AND total>=0),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','paid')),created_by TEXT NOT NULL REFERENCES el_users(id),approved_by TEXT REFERENCES el_users(id),paid_by TEXT REFERENCES el_users(id),accrual_journal_id TEXT,payment_journal_id TEXT,is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),UNIQUE(org_id,employee_id,month),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES el_employees(org_id,id),FOREIGN KEY(contract_id) REFERENCES el_contracts(id),FOREIGN KEY(org_id,accrual_journal_id) REFERENCES el_journals(org_id,id),FOREIGN KEY(org_id,payment_journal_id) REFERENCES el_journals(org_id,id));
CREATE INDEX el_staff_payroll_lookup ON el_staff_payroll(org_id,branch_id,month,status);
CREATE TRIGGER el_staff_payroll_guard BEFORE UPDATE ON el_staff_payroll BEGIN SELECT CASE WHEN NEW.total<>OLD.total OR NEW.calculation_json<>OLD.calculation_json OR NEW.employee_id<>OLD.employee_id OR NEW.month<>OLD.month OR NEW.contract_id<>OLD.contract_id THEN RAISE(ABORT,'Employee payroll calculation is immutable') END;SELECT CASE WHEN NOT((OLD.status='draft' AND NEW.status='approved' AND NEW.approved_by<>OLD.created_by) OR (OLD.status='approved' AND NEW.status='paid' AND NEW.paid_by<>OLD.created_by AND NEW.paid_by<>OLD.approved_by)) THEN RAISE(ABORT,'Employee payroll requires separate preparer approver and payer') END;END;
CREATE TRIGGER el_staff_payroll_delete BEFORE DELETE ON el_staff_payroll WHEN OLD.is_demo=0 BEGIN SELECT RAISE(ABORT,'Employee payroll cannot be deleted'); END;
CREATE TABLE el_employee_shifts(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,employee_id TEXT NOT NULL,starts_at INTEGER NOT NULL,ends_at INTEGER NOT NULL,local_start TEXT NOT NULL,local_end TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','cancelled','completed')),notes TEXT NOT NULL DEFAULT '',is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(ends_at>starts_at AND ends_at-starts_at<=86400),FOREIGN KEY(org_id,employee_id) REFERENCES el_employees(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE INDEX el_employee_shifts_lookup ON el_employee_shifts(org_id,branch_id,starts_at);
CREATE INDEX el_employee_shifts_conflict ON el_employee_shifts(employee_id,status,starts_at,ends_at);
CREATE TRIGGER el_employee_shift_conflict BEFORE INSERT ON el_employee_shifts WHEN NEW.status='scheduled' BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM el_leave_requests WHERE employee_id=NEW.employee_id AND status='approved' AND starts_on<=NEW.local_end AND ends_on>=NEW.local_start) THEN RAISE(ABORT,'Employee shift overlaps approved leave') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM el_employee_shifts WHERE employee_id=NEW.employee_id AND status='scheduled' AND starts_at<NEW.ends_at AND ends_at>NEW.starts_at) THEN RAISE(ABORT,'Employee shift overlaps an existing shift') END;END;
CREATE TABLE el_notification_templates(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,name TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,channel TEXT NOT NULL DEFAULT 'in_app' CHECK(channel IN ('in_app','email','sms','whatsapp')),is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE INDEX el_notification_templates_lookup ON el_notification_templates(org_id,branch_id,name);

CREATE TRIGGER el_leave_shift_guard BEFORE UPDATE OF status ON el_leave_requests WHEN NEW.status='approved' BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM el_employee_shifts WHERE employee_id=NEW.employee_id AND status='scheduled' AND local_start<=NEW.ends_on AND local_end>=NEW.starts_on) THEN RAISE(ABORT,'Approved leave overlaps scheduled shifts') END; END;
